from decimal import Decimal, getcontext, ROUND_HALF_UP, ROUND_DOWN, InvalidOperation
import math

getcontext().prec = 80

_TWO = Decimal("0.01")

# Valores por defecto tomados de 02_parametros.sql (solo se usan si el parametro no llega en 'params').
_DEFAULT_PARAMS = {
    "DIAS_MAX_DENUNCIA": "30",
    "DIAS_MAX_DENUNCIA_VIDA": "365",
    "DEDUCIBLE_MINIMO": "100",
    "PCT_DESCUENTO_DED_VIP": "50",
    "TOLERANCIA_MORA_VIP": "500",
    "MAX_SINIESTROS_ANUAL": "3",
    "PCT_PENALIZACION_SINIEST": "10",
    "UMBRAL_RETENCION": "10000",
    "TASA_RETENCION": "2",
    "TOPE_AUTO_APROBACION": "50000",
    "DIAS_ALERTA_FRAUDE": "15",
    "PCT_ALERTA_FRAUDE": "80",
    "FACTOR_INFLACION": "1.035",
    "TASA_IVA": "19",
}


def _dec(v, default="0"):
    if v is None:
        return Decimal(default)
    s = str(v).strip().strip('"').strip("'")
    if s == "" or s.upper() in ("NULL", "NONE"):
        return Decimal(default)
    try:
        return Decimal(s)
    except InvalidOperation:
        return Decimal(default)


def _r2(x):
    # ROUND(x, 2) de Oracle: mitad alejandose de cero (== ROUND_HALF_UP de decimal)
    return Decimal(x).quantize(_TWO, rounding=ROUND_HALF_UP)


def _num14_2(x):
    # Asignacion a NUMBER(14,2): Oracle redondea a la escala del destino
    return _r2(x)


def _fmt2(x):
    return str(Decimal(x).quantize(_TWO, rounding=ROUND_HALF_UP))


def _parse_bool(v):
    if isinstance(v, bool):
        return v
    s = str(v if v is not None else "").strip().strip('"').strip("'").upper()
    return s in ("TRUE", "1", "S", "SI", "Y", "YES", "T", "V", "VERDADERO")


def _days_from_civil(y, m, d):
    y2 = y - 1 if m <= 2 else y
    era = (y2 if y2 >= 0 else y2 - 399) // 400
    yoe = y2 - era * 400
    mp = (m + 9) % 12
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def _parse_date(v):
    # TRUNC(fecha): se ignora la parte horaria. Formato esperado YYYY-MM-DD.
    s = str(v).strip().strip('"').strip("'")[:10]
    parts = s.replace("/", "-").split("-")
    y, m, d = int(parts[0]), int(parts[1]), int(parts[2])
    return _days_from_civil(y, m, d)


def _parse_params(p):
    result = {}
    if p is None:
        return result
    if isinstance(p, dict):
        for k, v in p.items():
            result[str(k).strip().upper()] = v
        return result
    s = str(p).strip()
    if s.startswith("{") and s.endswith("}"):
        s = s[1:-1]
    # separadores admitidos: ',', ';', saltos de linea
    s = s.replace(";", ",").replace("\n", ",").replace("\r", ",")
    for item in s.split(","):
        item = item.strip()
        if not item:
            continue
        if ":" in item:
            k, v = item.split(":", 1)
        elif "=" in item:
            k, v = item.split("=", 1)
        else:
            continue
        k = k.strip().strip('"').strip("'").strip().upper()
        v = v.strip().strip('"').strip("'").strip()
        result[k] = v
    return result


def run(inp: dict) -> dict:
    params = _parse_params(inp.get("params"))

    def P(name):
        v = params.get(name)
        if v is None or str(v).strip() == "" or str(v).strip().upper() in ("NULL", "NONE"):
            v = _DEFAULT_PARAMS.get(name, "0")
        return _dec(v)

    out = {
        "status": "",
        "reason_code": "",
        "base_amount": "0.00",
        "deductible_amount": "0.00",
        "covered_amount": "0.00",
        "withholding_amount": "0.00",
        "net_amount": "0.00",
        "observations": "",
        "claim_final_status": "",
    }

    estado_a_siniestro = {
        "APROBADA": "LIQUIDADO",
        "RECHAZADA": "RECHAZADO",
        "PENDIENTE_APROBACION": "PENDIENTE_REVISION",
    }

    def rechazar(motivo, obs=None):
        r = dict(out)
        r["status"] = "RECHAZADA"
        r["reason_code"] = motivo
        r["base_amount"] = "0.00"
        r["deductible_amount"] = "0.00"
        r["covered_amount"] = "0.00"
        r["withholding_amount"] = "0.00"
        r["net_amount"] = "0.00"
        r["observations"] = obs if obs else ""
        r["claim_final_status"] = "RECHAZADO"
        return r

    claim_status = str(inp.get("claim_status", "")).strip()
    # ORA-20001: siniestro no REGISTRADO -> excepcion, no se inserta liquidacion
    if claim_status != "REGISTRADO":
        r = dict(out)
        r["status"] = "ERROR"
        r["reason_code"] = "ORA-20001"
        r["claim_final_status"] = claim_status
        return r

    claimed = _num14_2(_dec(inp.get("claimed_amount")))
    occ = _parse_date(inp.get("occurrence_date"))
    rep = _parse_date(inp.get("report_date"))
    pol_status = str(inp.get("policy_status", "")).strip()
    branch = str(inp.get("policy_branch", "")).strip()
    pol_start = _parse_date(inp.get("policy_start_date"))
    pol_end = _parse_date(inp.get("policy_end_date"))
    sum_insured = _num14_2(_dec(inp.get("sum_insured")))
    ded_type = str(inp.get("deductible_type", "")).strip()
    ded_value = _num14_2(_dec(inp.get("deductible_value")))
    pending = _num14_2(_dec(inp.get("pending_premium")))
    category = str(inp.get("customer_category", "")).strip()
    cov_found = _parse_bool(inp.get("coverage_found"))
    cov_limit = _num14_2(_dec(inp.get("coverage_limit")))
    cov_pct = _r2(_dec(inp.get("coverage_pct")))
    waiting = int(_dec(inp.get("waiting_days")).to_integral_value(rounding=ROUND_HALF_UP))
    prior_count = int(_dec(inp.get("prior_liquidated_claims_365d")).to_integral_value(rounding=ROUND_DOWN))
    total_indem = _dec(inp.get("total_indemnified"))

    obs = None

    def add_obs(o, mark):
        return mark if not o else o + ";" + mark

    # 1.a Estado de la poliza
    if pol_status != "VIGENTE":
        return rechazar("POLIZA_NO_VIGENTE")

    # 1.b Vigencia (extremos inclusive)
    if occ < pol_start or occ > pol_end:
        return rechazar("FUERA_DE_VIGENCIA")

    # 1.c Plazo de denuncia
    dias_denuncia = rep - occ
    if branch == "VIDA":
        dias_max = P("DIAS_MAX_DENUNCIA_VIDA")
    else:
        dias_max = P("DIAS_MAX_DENUNCIA")
    if Decimal(dias_denuncia) > dias_max:
        return rechazar("DENUNCIA_EXTEMPORANEA")

    # 1.d Cobertura contratada
    if not cov_found:
        return rechazar("COBERTURA_NO_CONTRATADA")

    # 1.e Carencia
    dias_desde_inicio = occ - pol_start
    if dias_desde_inicio < waiting:
        return rechazar("EN_PERIODO_CARENCIA")

    # 1.f Morosidad
    if pending > 0:
        tol = P("TOLERANCIA_MORA_VIP")
        if category == "VIP" and pending <= tol:
            obs = add_obs(obs, "TOLERANCIA_MORA_VIP")
        else:
            return rechazar("PRIMA_EN_MORA", obs)

    # 2.a Monto base
    if claimed > cov_limit:
        base = _num14_2(cov_limit)
        obs = add_obs(obs, "LIMITE_COBERTURA")
    else:
        base = _num14_2(claimed)

    # 2.b Deducible (v_deducible NUMBER(14,2))
    if ded_type == "FIJO":
        ded = _num14_2(ded_value)
    else:
        ded_min = P("DEDUCIBLE_MINIMO")
        ded = _num14_2(_r2(base * ded_value / Decimal(100)))
        if ded < ded_min:
            ded = _num14_2(ded_min)
            obs = add_obs(obs, "DEDUCIBLE_MINIMO")
    if category == "VIP" and ded > 0:
        pct_vip = P("PCT_DESCUENTO_DED_VIP")
        ded = _num14_2(_r2(ded * (Decimal(100) - pct_vip) / Decimal(100)))
        obs = add_obs(obs, "DESCUENTO_VIP")

    # 2.c Monto cubierto
    cub = _num14_2(_r2((base - ded) * cov_pct / Decimal(100)))
    if cub <= 0:
        return rechazar("BAJO_DEDUCIBLE", obs)

    # 2.d Siniestralidad
    if Decimal(prior_count) >= P("MAX_SINIESTROS_ANUAL"):
        cub = _num14_2(_r2(cub * (Decimal(100) - P("PCT_PENALIZACION_SINIEST")) / Decimal(100)))
        obs = add_obs(obs, "PENALIZACION_SINIESTRALIDAD")

    # 2.e Suma asegurada remanente
    remanente = sum_insured - total_indem
    if remanente <= 0:
        return rechazar("SUMA_ASEGURADA_AGOTADA", obs)
    if cub > remanente:
        cub = _num14_2(remanente)
        obs = add_obs(obs, "TOPE_SUMA_ASEGURADA")

    # 2.f Retencion
    if branch != "VIDA" and cub > P("UMBRAL_RETENCION"):
        ret = _num14_2(_r2(cub * P("TASA_RETENCION") / Decimal(100)))
        obs = add_obs(obs, "RETENCION_APLICADA")
    else:
        ret = Decimal("0.00")

    neto = _num14_2(cub - ret)

    # 3. Estado final
    umbral_fraude = _r2(cov_limit * P("PCT_ALERTA_FRAUDE") / Decimal(100))
    if Decimal(dias_desde_inicio) <= P("DIAS_ALERTA_FRAUDE") and claimed >= umbral_fraude:
        estado = "PENDIENTE_APROBACION"
        motivo = "SOSPECHA_FRAUDE"
    elif neto > P("TOPE_AUTO_APROBACION"):
        estado = "PENDIENTE_APROBACION"
        motivo = "SUPERA_TOPE_AUTOMATICO"
    else:
        estado = "APROBADA"
        motivo = "LIQUIDACION_AUTOMATICA"

    r = dict(out)
    r["status"] = estado
    r["reason_code"] = motivo
    r["base_amount"] = _fmt2(base)
    r["deductible_amount"] = _fmt2(ded)
    r["covered_amount"] = _fmt2(cub)
    r["withholding_amount"] = _fmt2(ret)
    r["net_amount"] = _fmt2(neto)
    r["observations"] = obs if obs else ""
    r["claim_final_status"] = estado_a_siniestro[estado]
    return r
